import "sync"

// FanIn runs fn over every input concurrently and returns the results in the
// same order as the inputs. It currently deadlocks on any non-empty input.
func FanIn(inputs []int, workers int, fn func(int) int) []int {
	out := make([]int, len(inputs))
	jobs := make(chan int)
	var wg sync.WaitGroup

	for w := 0; w < workers; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for i := range jobs {
				out[i] = fn(inputs[i])
			}
		}()
	}

	for i := range inputs {
		jobs <- i
	}
	close(jobs)
	wg.Wait()
	return out
}

package cache

import (
	"container/list"
)

type entry struct {
	key   string
	value int
}

type LRU struct {
	capacity  int
	items     map[string]*list.Element
	evictList *list.List
}

// NewLRU initializes a new LRU cache with the given capacity.
func NewLRU(capacity int) *LRU {
	return &LRU{
		capacity:  capacity,
		items:     make(map[string]*list.Element),
		evictList: list.New(),
	}
}

// Get retrieves a value from the cache. If the key exists, it moves the entry to the front.
func (c *LRU) Get(key string) (int, bool) {
	if ent, ok := c.items[key]; ok {
		c.evictList.MoveToFront(ent)
		return ent.Value.(*entry).value, true
	}
	return 0, false
}

// Put adds or updates a value in the cache. If the cache is full, it evicts the least recently used entry.
func (c *LRU) Put(key string, value int) {
	if c.capacity <= 0 {
		return
	}

	// If key exists, update value and move to front
	if ent, ok := c.items[key]; ok {
		c.evictList.MoveToFront(ent)
		ent.Value.(*entry).value = value
		return
	}

	// If at capacity, evict the oldest
	if c.evictList.Len() >= c.capacity {
		c.removeOldest()
	}

	// Add new entry to the front
	ent := &entry{key, value}
	element := c.evictList.PushFront(ent)
	c.items[key] = element
}

// Len returns the current number of items in the cache.
func (c *LRU) Len() int {
	return c.evictList.Len()
}

func (c *LRU) removeOldest() {
	ent := c.evictList.Back()
	if ent != nil {
		c.evictList.Remove(ent)
		kv := ent.Value.(*entry)
		delete(c.items, kv.key)
	}
}

export function groupConsecutive(values: number[]): number[][] {
  if (values.length === 0) {
    return [];
  }

  const result: number[][] = [];
  let currentRun: number[] = [values[0]];

  for (let i = 1; i < values.length; i++) {
    if (values[i] === values[i - 1] + 1) {
      currentRun.push(values[i]);
    } else {
      result.push(currentRun);
      currentRun = [values[i]];
    }
  }

  result.push(currentRun);
  return result;
}

export type Fetcher = (id: string) => Promise<{ id: string; parent: string | null }>;

// Walks from a node to the root and returns the chain, root last.
// Rewrite this to use async/await and a plain loop. Behaviour must not change,
// including that a cycle throws Error("cycle detected") and that the chain is
// capped at 50 entries with Error("chain too long").
export async function ancestry(fetch: Fetcher, start: string): Promise<string[]> {
  const seen = new Set<string>();
  const chain: string[] = [];
  let currentId: string | null = start;

  while (currentId !== null) {
    if (seen.has(currentId)) {
      throw new Error("cycle detected");
    }
    seen.add(currentId);
    chain.push(currentId);

    if (chain.length > 50) {
      throw new Error("chain too long");
    }

    const node = await fetch(currentId);
    currentId = node.parent;
  }

  return chain;
}

